"""Async builder widgets — render the loading / error / done lifecycle of an
async source declaratively, instead of hand-rolling ``State`` flags.

``FutureBuilder`` runs a one-shot awaitable (``http.*``, ``workpeg.*``, or any
promise-returning call) once per ``key``; ``StreamBuilder`` subscribes to a
Server-Sent Events stream and rebuilds as messages arrive. Both build their
result widget with a ``done`` builder; the data crosses as inert values.
"""
from __future__ import annotations

from typing import Any, Callable

from workpeg.ui.state import Binding
from workpeg.ui.widgets.base import BaseWidget, WidgetChild


class FutureBuilder(BaseWidget):
    """Render the lifecycle of a one-shot async call. ``future`` is fired **once
    per ``key``** (change the key to refetch) — a lambda (or method) returning an
    awaitable, e.g. ``http.*`` or ``workpeg.*``. ``done(data)`` builds the result
    widget, ``error(e)`` the error widget, and ``loading`` shows while pending::

        FutureBuilder(
            future=lambda: workpeg.get_protected("/v1/dogs"),
            key="dogs",
            loading=Spinner(),
            error=lambda e: Text(f"Couldn't load: {e}", variant="muted"),
            done=lambda dogs: Column(*[ListTile(title=d) for d in dogs]),
        )

    The result is cached per key on the page, so a re-render doesn't refetch;
    navigating away and back (a fresh page) does. ``done``/``error`` receive the
    data / error as inert values — render them safely like any other text.
    """

    widget_type = "FutureBuilder"

    def __init__(
        self,
        *,
        future: Callable,
        done: Callable,
        key: str | Binding,
        loading: WidgetChild | None = None,
        error: Callable | WidgetChild | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.future = future
        self.done = done
        self.loading = loading
        self.error = error


class StreamBuilder(BaseWidget):
    """Subscribe to a Server-Sent Events stream and rebuild as messages arrive.
    ``stream`` is an ``http(s)://`` URL (may be dynamic); ``done(messages)`` is
    rebuilt with the accumulated messages (newest last) on each event. The
    connection is opened once per ``key`` and closed automatically on
    navigation::

        StreamBuilder(
            stream="https://stream.example/feed",
            key="feed",
            loading=Spinner(),
            done=lambda messages: Column(*[Text(m) for m in messages[-20:]]),
        )

    One-way (server → client), so there is no send; reach for the ``events`` /
    ``socket`` sentinels when you need imperative control. Messages cross as
    inert strings.
    """

    widget_type = "StreamBuilder"

    def __init__(
        self,
        *,
        stream: str | Binding,
        done: Callable,
        key: str | Binding,
        loading: WidgetChild | None = None,
        error: Callable | WidgetChild | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.stream = stream
        self.done = done
        self.loading = loading
        self.error = error
